  "summary": "The original code suffered from critical memory leaks, insecure session ID generation, and poor architectural patterns. I have refactored the module into a class-based structure with cryptographically secure IDs, automatic TTL-based cleanup, and input validation to ensure production readiness.",
  "fixed_code": "const crypto = require('crypto');

/**
 * Manages user sessions with automatic expiration.
 */
class SessionManager {
    constructor(ttlMs = 3600000) {
        this.sessions = new Map();
        this.ttlMs = ttlMs;
        // Cleanup interval to prevent memory leaks
        setInterval(() => this.prune(), 60000).unref();
    }

    /**
     * @param {string} userId 
     * @returns {string}
     */
    createSession(userId) {
        if (typeof userId !== 'string' || userId.length === 0) {
            throw new Error('Invalid userId');
        }
        const sessionId = crypto.randomBytes(32).toString('hex');
        this.sessions.set(sessionId, { userId, createdAt: Date.now() });
        return sessionId;
    }

    getSession(sessionId) {
        const session = this.sessions.get(sessionId);
        if (!session) return null;
        if (Date.now() - session.createdAt > this.ttlMs) {
            this.sessions.delete(sessionId);
            return null;
        }
        return session;
    }

    prune() {
        const now = Date.now();
        for (const [id, data] of this.sessions) {
            if (now - data.createdAt > this.ttlMs) this.sessions.delete(id);
        }
    }
}

module.exports = new SessionManager();"
